:root {
    /* The board was a hard 600px square, so on a 390px phone it ran from
       -111px to 501px and the left and right columns could not be tapped at
       all. Sizing it against both axes keeps the whole grid reachable, and
       the 190px reserve leaves room for the heading and Play Again button. */
    --board-size: min(600px, calc(100vw - 24px), calc(100vh - 190px));
}

* {
    user-select: none
}

body {
    margin: 0;
}

.container {
    display: flex;
    align-items: center;
    justify-content: center;
    height: 100vh;
    padding: 12px;
    box-sizing: border-box;
}

@supports (height: 100dvh) {
    .container {
        height: 100dvh;
    }
}

#board {
    width: var(--board-size);
    height: var(--board-size);
    margin: 0 auto;
    background-color: #231f20;
    color: #62c559;
    border: 6px solid #62c559;
    border-radius: 10px;
    box-sizing: border-box;
    display: grid;
    grid-template: repeat(3, 1fr) / repeat(3, 1fr);
}

.box {
    border: 6px solid #62c559;
    font-family: Helvetica;
    font-weight: bold;
    /* Scales with the board instead of a fixed 4em, which overflowed the cell
       once the board shrank. */
    font-size: calc(var(--board-size) / 4);
    display: flex;
    justify-content: center;
    align-items: center;
    cursor: pointer;
    /* Removes the ~300ms tap delay on the cells. */
    touch-action: manipulation;
}

.row {
    display: flex;
    justify-content: space-between;
    align-items: center;
    /* The heading and the button sat side by side and pushed each other off a
       narrow screen; let them stack instead. */
    flex-wrap: wrap;
    gap: 8px;
    max-width: var(--board-size);
    margin: 0 auto;
}

#info {
    font-size: clamp(1.1rem, 5vw, 2rem);
    margin: 8px 0;
}

.button {
    background-color: #62c559;
    border: none;
    border-radius: 6px;
    color: white;
    padding: 16px 32px;
    text-align: center;
    text-decoration: none;
    text-transform: uppercase;
    font-size: 16px;
    margin-top: 16px;
    margin-bottom: 16px;
    cursor: pointer;
    /* Was a fixed 200px, which together with the heading overflowed a phone. */
    width: auto;
    min-width: 140px;
    flex-shrink: 0;
    touch-action: manipulation;
}

.button:active, .button:focus {
    outline: 0;
    border: none;
    -moz-outline-style: none;
}

.button:disabled {
    cursor: not-allowed;
    background-color: #e7e7e7;
}

.button-hoverable span {
    cursor: pointer;
    display: inline-block;
    position: relative;
    transition: 0.5s;
}

.button-hoverable span:after {
    content: '\00bb';
    position: absolute;
    opacity: 0;
    top: 0;
    right: -20px;
    transition: 0.5s;
}

.button-hoverable:hover span {
    padding-right: 25px;
}

.button-hoverable:hover span:after {
    opacity: 1;
    right: 0;
}

